COURSE = dict(id="research-reports-sebi", level="expert", title="Research reports and SEBI rules", sec="stocks", track="research", topic="Research rules", tag="RA",
  blurb="How a research report is built, and the SEBI rules for research analysts: registration, disclosures, conflicts and records.",
  hook="A research report moves money. That is why the rules around it are strict.",
  fun=["A research analyst registered with SEBI is expected to hold the NISM Series XV certification.", "Research analysts must keep their research records for several years, so any recommendation can be traced back."],
  traps=["Promising or guaranteeing returns in a report.", "Hiding that you or your employer hold the shares.", "Skipping the records that show the basis for a recommendation."],
  lessons=[
  dict(title="Who is a research analyst", intro="Research is a regulated activity in India.", concepts=[
    ("Research analyst", "A research analyst is a person who prepares or publishes research on securities, such as reports and recommendations.", "A professional publishes a note rating a listed bank as a buy."),
    ("Research report", "A research report is a written analysis of a company or security that gives a view and the reasons behind it.", "A note explains why a firm is expected to grow faster than its peers."),
    ("SEBI registration", "SEBI registration is the licence a research analyst must hold from the securities regulator before offering research.", "An individual cannot sell stock recommendations as a business without this permission."),
    ("NISM Series XV", "NISM Series XV is the certification exam for research analysts, covering markets, analysis methods and the regulations.", "An aspiring analyst prepares for the exam on research methods and rules.")],
    client=("“Can anyone give stock recommendations on social media?”", "A client following online tipsters."), talk="“Giving recommendations as a business needs registration with SEBI. Check the registration number before you act on anyone's advice.”", remember=["Research needs registration.", "Check the registration number.", "The qualification includes NISM Series XV."]),
  dict(title="Building a report", intro="A good report shows its thinking, not only its conclusion.", concepts=[
    ("Investment thesis", "An investment thesis is the central reason an analyst believes a share will do well or badly.", "A note argues that rising demand and falling costs will lift margins."),
    ("Rating", "A rating is an analyst's simple call on a security, such as buy, hold or sell.", "A report labels a share a hold because the upside is small."),
    ("Key risks", "Key risks are the main things that could make the analyst's view wrong.", "A weak monsoon or a change in rules could hurt the forecast."),
    ("Assumptions", "Assumptions are the stated inputs behind a forecast, such as growth, margins and the discount rate.", "A model states that sales will grow 15% a year for five years.")],
    client=("“The report says buy. What if it is wrong?”", "A client relying on a rating."), talk="“Read the thesis and the key risks, not only the rating. They tell you what must go right and what could go wrong.”", remember=["A report states its thesis.", "Risks belong in every report.", "Assumptions must be visible."]),
  dict(title="Conflicts and disclosures", intro="Readers must be told about anything that could colour the view.", concepts=[
    ("Conflict of interest", "A conflict of interest is a situation where an analyst's own gain could affect the objectivity of the research.", "An analyst owns shares in the company she is about to rate."),
    ("Disclosure", "A disclosure is a statement in the report of holdings, relationships and payments that could affect the view.", "A report states that the firm's employees hold shares in the company it covers."),
    ("Trading restriction", "A trading restriction bars analysts from trading in a security around the time they publish research on it.", "An analyst cannot buy a share in the weeks before and after releasing her report on it."),
    ("Chinese wall", "A Chinese wall is an internal barrier that stops sensitive information passing between departments of a firm.", "The investment banking team cannot share a deal's details with the research team.")],
    client=("“Does the analyst own the stock they recommend?”", "A client doubting objectivity."), talk="“Good reports disclose holdings and any relationship with the company. If it is not disclosed, ask.”", remember=["Disclose interests.", "Restrict trading around reports.", "Keep the research team independent."]),
  dict(title="Conduct and records", intro="How an analyst behaves matters as much as what the report says.", concepts=[
    ("Fair presentation", "Fair presentation means a report gives a balanced picture, with facts separated from opinions and no misleading claims.", "A note shows the risks as clearly as the upside."),
    ("Guaranteed returns", "Guaranteed returns are promises of fixed or assured gains from investing, which research analysts must not make.", "A message claims a stock will surely double in six months."),
    ("Record keeping", "Record keeping is the duty to preserve research, supporting data and communications for the period set by the regulator.", "An analyst can show the workings behind a recommendation made two years ago."),
    ("Public appearance", "A public appearance is when an analyst speaks about securities in media, events or online, where disclosures also apply.", "An analyst states her holdings before commenting on a news channel.")],
    client=("“The adviser in the group promised a safe 30% return. Is that normal?”", "A client attracted by a promise."), talk="“No one can guarantee returns in markets. A promise like that is a red flag. Check the registration and report it.”", remember=["Never promise returns.", "Keep records of the basis.", "Disclose in public comments."]),
  dict(title="Writing for readers", intro="Research is useful only when the reader can understand and check it.", concepts=[
    ("Plain language", "Plain language is writing clearly and simply so that the reader can understand and act on the research.", "A report explains a ratio in one sentence instead of using jargon."),
    ("Base, bull and bear case", "Base, bull and bear case are three views of a forecast: the most likely, the optimistic and the pessimistic.", "A note shows values of ₹700, ₹900 and ₹500 for the same share."),
    ("Data source", "A data source is the origin of a number in a report, which should be named so readers can check it.", "A table cites the company's annual report and exchange filings under each chart."),
    ("Update and review", "Update and review is the practice of revisiting a recommendation when new facts arrive, and saying when it changes.", "After a profit warning, the analyst revises the rating and explains why.")],
    client=("“How do I know if a research report is trustworthy?”", "A client judging a report."), talk="“Look for a clear thesis, named sources, stated risks, disclosures and a record of updating its views. Be wary of reports that are all upside.”", remember=["Clear thesis, named sources.", "Show a range, not one number.", "Update when facts change."]),
  ])
